alter table week_content add column recommendations_text text not null default '';

insert into content_release (version, approved_by, approved_at)
values ('book-2026-11', 'clinical-book', now())
on conflict (version) do nothing;

update app_setting
set setting_value = 'book-2026-11'
where setting_key = 'content.version';

update week_content
set warning_text = $w$Срочно обратитесь за медицинской помощью при: рвоте более 5 раз в сутки; потере веса более 3 кг за 1–1,5 недели; давлении выше 120/80; размытии или мигании перед глазами; сильной головной боли; боли внизу живота любого характера; боли в области желудка; отёке лица, рук или ног; кровянистых или обильных жидких выделениях; температуре выше 37,5 °C; отсутствии или изменении шевелений плода более 12 часов после 20 недель. При тревожных симптомах звоните 103 или 112.$w$
where week_from between 4 and 42;

update week_content w
set title              = v.title,
    fetal_text         = v.fetal,
    nutrition_text     = v.nutrition,
    recommendations_text = v.recommendations,
    version            = 'book-2026-11'
from (values
    (4, 4,
     $t$Неделя 4: имплантация и первые клетки$t$,
     $t$Идёт имплантация эмбриона и закладка нервной трубки. Формируются основы нервной и сердечно-сосудистой систем.$t$,
     $t$Особенно важен фолат: тёмно-зелёные овощи, бобовые, орехи. Откажитесь от алкоголя и курения. Ограничьте кофеин до 300 мг в сутки, избегайте сырой рыбы и мяса, непастеризованного молока, мягких сыров и паштетов.$t$,
     $t$Запишитесь к акушеру-гинекологу: первый визит желательно до 10 недель. Начните приём фолатов и витаминов по назначению врача. Избегайте контактных видов спорта, падений и тяжёлых физических нагрузок. При резус-отрицательной крови обсудите обследование партнёра.$t$),
    (5, 8,
     $t$Недели 5–8: формируются органы$t$,
     $t$Формируются сердце, мозг, конечности и черты лица. Это период максимальной уязвимости к внешним воздействиям. Плод начинает двигаться, хотя вы этого ещё не чувствуете.$t$,
     $t$Ежедневно получайте белок и фолаты. Подходят кисломолочные продукты, творог, зелёные овощи, яйца, брокколи, шпинат, овсяная каша, индейка. Не ешьте сырые яйца, рыбу и мясо с кровью, непастеризованное молоко, мягкие сыры, паштеты и печень. Ограничьте кофеин.$t$,
     $t$Первый визит к врачу до 10 недель. Принимайте витамины по назначению. Откажитесь от алкоголя и курения — безопасной дозы не существует. При кровянистых выделениях, сильной боли или температуре обращайтесь срочно.$t$),
    (9, 12,
     $t$Недели 9–12: конец первого триместра$t$,
     $t$Сформированы основные органы. Появляются пальцы, продолжает развиваться лицо. В 11–13 недель и 6 дней проводится первый комбинированный скрининг: УЗИ и биохимический анализ крови.$t$,
     $t$Добавьте кисломолочные продукты, квашеную капусту, сухофрукты, нежирную говядину, фрукты и морсы. Питание должно быть регулярным и разнообразным, без резких ограничений. Пейте достаточно воды, ограничьте кофеин.$t$,
     $t$Пройдите первый скрининг в 11–13 недель 6 дней. Проверьте резус-фактор; при отрицательном резусе обсудите контроль антирезусных антител. Соблюдайте питьевой режим и режим сна. При кровянистых или водянистых выделениях обращайтесь срочно.$t$),
    (13, 16,
     $t$Недели 13–16: второй триместр$t$,
     $t$Формируется хрящевая ткань, продолжает развиваться пищеварительная система, появляется лануго. Размер плода около 10 см, вес 40–50 г.$t$,
     $t$Молоко и кисломолочные продукты, творог, кефир, сыр, нежирные рыба и мясо, фрукты и овощи. Белок и кальций важны для роста. Ограничьте сладкие напитки и выпечку.$t$,
     $t$Продолжайте наблюдение у врача. Двигайтесь 20–30 минут в день при хорошем самочувствии. Половые контакты не запрещены при нормальном самочувствии; при боли, кровянистых выделениях, зуде или жжении во влагалище обратитесь к врачу. pH влагалища можно проверять тест-полоской раз в две недели.$t$),
    (17, 20,
     $t$Недели 17–20: шевеления и второй скрининг$t$,
     $t$Плод слышит звуки, активно двигается, формируется жировая ткань. С 17–21 недели многие женщины начинают чувствовать шевеления. В 18–20 недель проводится второй скрининг УЗИ.$t$,
     $t$Капуста, болгарский перец, морковь, постное мясо птицы или кролика, рыба, яйца, ягоды и зелень. Железо: мясо, гречка, бобовые. Кальций: молочные продукты, кунжут, зелень.$t$,
     $t$Пройдите второе УЗИ в 18–20 недель. При резус-отрицательной крови контролируйте антирезусные антитела. Начните замечать шевеления. Не лежите подолгу на спине. При отсутствии шевелений более 12 часов после 20 недель обращайтесь срочно.$t$),
    (21, 24,
     $t$Недели 21–24: середина беременности$t$,
     $t$Плод заглатывает околоплодные воды, развиваются лёгкие и репродуктивная система. Костный мозг участвует в кроветворении. Вес около 400–800 г.$t$,
     $t$Продолжайте сбалансированное питание: овощи, белок, цельнозерновые продукты, молочные продукты. Если врач назначил тест на глюкозу, следуйте инструкции. Ограничьте быстрые углеводы и сладкие напитки.$t$,
     $t$В 24–28 недель врач может назначить тест на гестационный диабет. Следите за прибавкой веса и давлением. Пейте достаточно воды, добавляйте продукты с клетчаткой для профилактики запоров. При отёках, головной боли или ухудшении зрения обращайтесь срочно.$t$),
    (25, 28,
     $t$Недели 25–28: начало третьего триместра$t$,
     $t$Плод активно набирает массу, открывает веки, различает звуки. Вес около 800–1100 г. С 28 недель начинается третий триместр.$t$,
     $t$Зерновые каши, супы на нежирном бульоне, тушёные овощи, запечённое или отварное мясо. Добавляйте клетчатку и воду для профилактики запоров. Ограничьте соль до 8 г в сутки.$t$,
     $t$С 28 недель следите за шевелениями. При резус-отрицательной крови обсудите введение антирезусного иммуноглобулина в 28–30 недель. Не лежите на спине. Начните обсуждать план родов и сумку в роддом. При отсутствии шевелений более 12 часов — срочно к врачу.$t$),
    (29, 32,
     $t$Недели 29–32: активный рост$t$,
     $t$Плод быстро набирает вес, укрепляются лёгкие и сердечно-сосудистая система. К 32 неделям вес около 1800 г. В 32 недели может проводиться КТГ для оценки сердечной деятельности плода.$t$,
     $t$Красная рыба, орехи, яйца, кисломолочные продукты. В последние месяцы ограничьте соль до 5–6 г в сутки, при склонности к отёкам обсудите с врачом ограничение свободной жидкости до 700–800 мл. Ужин делайте лёгким.$t$,
     $t$Посетите КТГ и УЗИ по назначению врача. Контролируйте шевеления, давление и вес. Не лежите на спине. Подготовьте сумку в роддом. При кровянистых или водянистых выделениях, сильной боли, отёке лица или рук обращайтесь срочно.$t$),
    (33, 36,
     $t$Недели 33–36: подготовка к встрече$t$,
     $t$Лёгкие почти готовы к дыханию, укрепляется сердечно-сосудистая система. К 35–37 неделям плод весит около 2,5 кг, рост около 48 см. Кости черепа остаются мягкими для родов.$t$,
     $t$Свежие фрукты, тушёные овощи, салаты, небольшое количество мяса. Питание регулярное, без переедания перед сном. Продолжайте пить воду и следить за прибавкой.$t$,
     $t$С 35–37 недель соберите сумку в роддом: документы, тапочки, маски, вода, гигиена, 2 ночные рубашки, пелёнки, послеродовые прокладки, халат, кружка и ложка, зарядка, эластичные бинты или компрессионные чулки, вещи для ребёнка, памперсы. Обсудите с врачом план родов и посетите перинатального психолога при желании. При схватках чаще чем через 10 минут, излитии вод, кровянистых выделениях или резкой боли — ехать в роддом.$t$),
    (37, 40,
     $t$Недели 37–40: доношенная беременность$t$,
     $t$С 37 недель беременность считается доношенной. Плод готов к рождению, может отойти слизистая пробка. Роды могут начаться в любой момент.$t$,
     $t$Свежие фрукты, тушёные овощи, салаты, мясо в небольших количествах. Не переедайте, выбирайте лёгкую пищу. Продолжайте пить воду.$t$,
     $t$Не отправляйтесь в дальние поездки. Следите за шевелениями. Ехать в роддом при излитии вод, регулярных схватках чаще чем через 10 минут, резкой боли внизу живота или кровянистых выделениях. Возьмите с собой документы, полис, СНИЛС, родовой сертификат и сумку.$t$),
    (41, 42,
     $t$Недели 41–42: наблюдение после ПДР$t$,
     $t$Беременность считается переношенной после 42 недель. После предполагаемой даты родов нужен более частый контроль состояния плода и плаценты.$t$,
     $t$Питание остаётся регулярным и умеренным. Пейте достаточно воды, не ограничивайте соль без рекомендации врача.$t$,
     $t$Обсудите с врачом план наблюдения: КТГ, УЗИ и решение о родоразрешении по показаниям. Следите за шевелениями. При уменьшении шевелений, излитии вод, кровянистых выделениях или регулярных схватках обращайтесь в роддом.$t$)
) as v(wf, wt, title, fetal, nutrition, recommendations)
where w.week_from between v.wf and v.wt;
